WITH corpus_docs AS (SELECT memory_record_id,memory_version_id,head_revision,generation,content_hash FROM memory_search.retrieval_documents WHERE tenant_id=$1 AND namespace_key=$2 AND generation=$3), corpus AS (SELECT count(*)::float8 AS n FROM corpus_docs), doc_lengths AS (SELECT rt.memory_version_id,max(rt.document_length)::float8 AS dl FROM memory_search.retrieval_terms rt JOIN corpus_docs cd ON cd.memory_version_id=rt.memory_version_id WHERE rt.tenant_id=$1 AND rt.generation=$3 GROUP BY rt.memory_version_id), average AS (SELECT COALESCE(avg(dl),1.0)::float8 AS avgdl FROM doc_lengths), dfs AS (SELECT rt.term,count(DISTINCT rt.memory_version_id)::float8 AS df FROM memory_search.retrieval_terms rt JOIN corpus_docs cd ON cd.memory_version_id=rt.memory_version_id WHERE rt.tenant_id=$1 AND rt.generation=$3 AND rt.term=ANY($4::text[]) GROUP BY rt.term) SELECT cd.memory_record_id,cd.memory_version_id,cd.head_revision,cd.generation,cd.content_hash,sum(ln(1.0+((corpus.n-dfs.df+0.5)/(dfs.df+0.5))) *((rt.term_frequency::float8*2.2)/(rt.term_frequency::float8+1.2*(0.25+0.75*rt.document_length::float8/NULLIF(average.avgdl,0)))))::float8 AS bm25_score FROM memory_search.retrieval_terms rt JOIN corpus_docs cd ON cd.memory_version_id=rt.memory_version_id JOIN dfs ON dfs.term=rt.term CROSS JOIN corpus CROSS JOIN average WHERE rt.tenant_id=$1 AND rt.generation=$3 AND rt.term=ANY($4::text[]) GROUP BY cd.memory_record_id,cd.memory_version_id,cd.head_revision,cd.generation,cd.content_hash,corpus.n,average.avgdl ORDER BY bm25_score DESC,cd.memory_record_id,cd.memory_version_id LIMIT $5